import {cityUKPath} from './cities-data.js?v=20261024-cities01';
export const londonViews={
 'city-london-context':[['site','Thames site'],['networks','Connections'],['boundary','Which London?'],['global','Scales of connection']],
 'city-london-structure':[['zones','Land-use zones'],['centres','Multiple centres'],['ages','Building-age evidence'],['fringe','Urban-rural fringe']],
 'city-london-movements':[['suburban','Out to the suburbs'],['counter','Beyond the city'],['return','Back to inner areas'],['coexist','Overlapping processes']],
 'city-london-migration':[['routes','Routes and motives'],['services','People and services'],['evidence','Compare characteristics'],['balance','Arrivals minus departures']],
 'city-london-census':[['population','Census population'],['age','Compare median ages'],['balance','Components of change'],['households','Household size']]
};
export const londonRequirements=Object.fromEntries(Object.entries(londonViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const londonAnimated=(k,v)=>k==='city-london-context'?v==='networks':k==='city-london-movements'?v!=='coexist':k==='city-london-migration'?v!=='evidence':k==='city-london-census'?v==='balance':false;
export const londonCensus={date:'2021-03-21',populationMillions:{2011:8.17,2021:8.80},reportedGrowthPercent:7.7,medianAge:[['London',35],['England & Wales',40],['Tower Hamlets',30],['Bromley',41],['Richmond upon Thames',41]],householdSize:{2011:2.47,2021:2.54},nonUKBornShare:{2011:36.7,2021:40.6}};
const txt=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(d,c='#b9cbd2',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=6,c='#efa995')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f8e8df" stroke-width="1"/>`;
const panel=(x,y,w,title,sub='')=>`<rect x="${x}" y="${y}" width="${w}" height="${sub?70:46}" rx="12" fill="#35576c" stroke="#abc4ce"/>`+txt(x+12,y+27,title,13)+(sub?txt(x+12,y+52,sub,11):'');
const fig=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#eef2f2" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,l)=>`<a href="${u}" target="_blank" rel="noopener">${l}</a>`;
const populationSource='https://data.london.gov.uk/download/dfef036a-7255-40e5-9965-66ba49e10b77/d96edb95-0510-4b7e-8be9-e91cf6a70c46/census%202021%20migration%20and%20population.pdf';
const onsSource='https://www.ons.gov.uk/peoplepopulationandcommunity/populationandmigration/internationalmigration/bulletins/internationalmigrationenglandandwales/census2021';
const housingSource='https://www.london.gov.uk/sites/default/files/2023-10/Housing%20in%20London%202023.pdf';
const censusSource=()=>`<p class="geo-caption">${link(populationSource,'GLA Census 2021 analysis, November 2022')} · ${link(onsSource,'ONS birthplace definitions')} · ${link(housingSource,'GLA Housing in London 2023, chart 1.2')}. Census day: 21 March 2021; dated usual-resident estimates, not live figures. Selected values rounded as shown. ${link('https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/','Open Government Licence v3.0')}.</p>`;
export function londonEvidence(kind='age'){
 let b='';if(kind==='age'){b=txt(20,27,'MEDIAN AGE · CENSUS 2021',16)+txt(20,50,'Years · shared zero-based scale',12);for(let i=0;i<londonCensus.medianAge.length;i++){const[n,v]=londonCensus.medianAge[i],y=80+i*49;b+=txt(20,y,n,12)+`<rect x="205" y="${y-15}" width="${v*4}" height="23" rx="4" fill="${i===0?'#e8b09a':'#a7c8c1'}"/>`+txt(212+v*4,y+2,String(v),12);}b+=line('M205 313H385','#a6bfc9',1)+txt(201,333,'0',10)+txt(279,333,'20',10)+txt(359,333,'40',10);}
 else if(kind==='birthplace'){b=txt(20,28,'BORN OUTSIDE THE UK · LONDON',15)+txt(20,52,'% of usual residents · not annual arrivals',12);for(const[i,yr]of[2011,2021].entries()){const v=londonCensus.nonUKBornShare[yr],y=105+i*100;b+=txt(20,y+25,String(yr),13)+`<rect x="85" y="${y}" width="${v*6}" height="45" rx="7" fill="${i?'#e8b09a':'#a7c8c1'}"/>`+txt(95+v*6,y+28,v+'%',14);}b+=txt(20,320,'Same characteristic, two census dates',12);}
 else if(kind==='population'){b=txt(20,28,'GREATER LONDON · CENSUS COUNTS',15)+txt(20,52,'Millions of usual residents · rounded',12);for(const[i,yr]of[2011,2021].entries()){const v=londonCensus.populationMillions[yr],y=105+i*100;b+=txt(20,y+25,String(yr),13)+`<rect x="85" y="${y}" width="${v*30}" height="45" rx="7" fill="${i?'#e8b09a':'#a7c8c1'}"/>`+txt(95+v*30,y+28,v.toFixed(2),14);}b+=txt(20,320,'Census snapshot; not today’s population',12);}
 else{b=txt(20,28,'LONDON · AVERAGE HOUSEHOLD SIZE',14)+txt(20,52,'People per household · census estimates',12)+panel(25,110,180,'2011: 2.47','Mean, not each home')+panel(235,110,180,'2021: 2.54','Not a population count')+txt(20,280,'Households differ in size and composition',13)+txt(20,320,'Compare definitions, geography and dates',12);}
 return fig(b,'Dated census comparison. Read each area, measure, year and unit; a regional average does not describe every resident or neighbourhood.')+censusSource()+`<details class="geo-chart-values"><summary>Read the data</summary><table class="geo-data"><caption>Census 2021: selected London evidence</caption><thead><tr><th scope="col">Measure / area</th><th scope="col">Value</th></tr></thead><tbody>${(kind==='age'?londonCensus.medianAge.map(([a,v])=>[a,v+' years']):kind==='birthplace'?[['2011', '36.7%'],['2021','40.6%']]:kind==='population'?[['2011','8.17 million'],['2021','8.80 million']]:[['2011','2.47 people'],['2021','2.54 people']]).map(([a,v])=>`<tr><th scope="row">${a}</th><td>${v}</td></tr>`).join('')}</tbody></table></details>`;
}
const house=(x,y,scale=1,c='#abc7bd')=>`<g transform="translate(${x} ${y}) scale(${scale})"><path d="M0 18L20 0 40 18V48H0Z" fill="${c}" stroke="#e1e6df"/><rect x="16" y="30" width="9" height="18" fill="#203f54"/><path d="M7 23h7v7H7zM28 23h7v7h-7z" fill="#203f54"/></g>`;
const towers=(x,y,n=3)=>Array.from({length:n},(_,i)=>`<rect x="${x+i*24}" y="${y-i%2*20}" width="20" height="${65+i%2*20}" fill="#9bbac8" stroke="#d5e1e4"/>`+Array.from({length:6},(_,j)=>`<rect x="${x+5+i*24+j%2*8}" y="${y+10+Math.floor(j/2)*14-i%2*20}" width="4" height="6" fill="#24465d"/>`).join('')).join('');
export function londonScene(k,v,t=0){if(!londonViews[k])return '';if(!londonRequirements[k].includes(v))v=londonRequirements[k][0];t=londonAnimated(k,v)?Math.min(1,Math.max(0,Number(t)||0)):0;let b='',c='';
 if(k==='city-london-context'){
  if(v==='site'){b=txt(20,28,'LONDON’S THAMES SITE',17)+`<path d="M20 190Q85 150 150 198T290 195T420 165" fill="none" stroke="#8db8cc" stroke-width="32"/>`+line('M205 145L222 233','#efc3ab',12)+towers(160,86,3)+txt(38,85,'Slightly higher north bank',12)+txt(248,270,'Crossing',13)+line('M290 250L228 210','#c3d6dc',1)+txt(20,310,'Thames → estuary → North Sea',13)+txt(20,333,'Conceptual site diagram · N ↑ · not a surveyed map',11);c='Navigable river, crossing and local relief help explain the early site. Diagram simplifies the Thames and ground heights; it is not a flood-risk map. Modern growth has additional causes.';return fig(b,c)+`<p class="geo-caption">${link('https://www.londonmuseum.org.uk/collections/london-stories/timeline-roman-london-londinium/','London Museum: Roman site evidence')}</p>`;}
  if(v==='networks'){b=txt(20,28,'CONNECTING FUNCTIONS AND PLACES',14)+panel(125,135,195,'London','Government / services')+panel(20,55,155,'South-east England')+panel(245,55,175,'Other UK cities')+panel(20,260,155,'Europe / world')+panel(245,260,175,'Digital partners')+line('M95 103L180 135M330 103L265 135M95 260L180 205M330 260L265 205')+dot(95+85*t,103+32*t)+dot(330-65*t,103+32*t)+dot(95+85*t,260-55*t)+dot(330-65*t,260-55*t);c='Symbolic connections carry people, goods and information at regional, national and global scales. Dots are not measured volumes or journey times; a connection supports functions without guaranteeing equal access.';}
  else if(v==='boundary'){b=txt(20,28,'THREE MEANINGS OF “LONDON”',16)+`<ellipse cx="220" cy="180" rx="190" ry="115" fill="#537c8a44" stroke="#a7c5d0" stroke-dasharray="6 4"/><ellipse cx="220" cy="180" rx="128" ry="80" fill="#7c9b8d88" stroke="#b6d0c8"/>`+dot(215,174,11)+txt(235,176,'City of London',12)+txt(130,225,'Greater London',14)+txt(95,315,'Wider functional / commuter area',13);c='Conceptual nested areas, not real boundary geometry. The small City district differs from Greater London’s 32 boroughs plus the City; commuting links extend farther. Size and shape here do not measure area.';}
  else{b=txt(20,28,'LOCATE LONDON AND ITS LINKS',15)+`<path d="${cityUKPath}" fill="#7e9f96" stroke="#c6d8d1"/>`+dot(231.4,274,6)+line('M238 274L290 270','#edb9a3',2)+txt(295,275,'London',13)+txt(280,95,'National rail',12)+txt(280,115,'Regional travel',12)+txt(280,135,'Global networks',12)+txt(20,338,'N ↑ · generalised UK outline · approximate marker',11);c='London lies in south-east England beside the Thames. Natural Earth UK outline, public domain; approximate city-centre marker. Listed connections identify scales, not a plotted route network.';return fig(b,c)+`<p class="geo-caption">${link('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth, public domain')}</p>`;}
 }
 if(k==='city-london-structure'){
  if(v==='zones'||v==='fringe'){b=txt(20,28,v==='zones'?'LAND USE · A CONCEPTUAL PROFILE':'AT THE URBAN-RURAL FRINGE',14);if(v==='zones'){b+=towers(30,100,3)+house(133,160,.9)+house(183,160,.9)+house(265,160,1.1)+`<path d="M345 205L365 155 385 205Z" fill="#a6c4a5"/><rect x="350" y="215" width="60" height="25" fill="#a2b982"/>`+line('M20 243H420','#c3d4d5',2)+txt(28,272,'CBD',12)+txt(123,272,'Inner city',12)+txt(251,272,'Suburbs',12)+txt(347,272,'Fringe',12)+txt(20,320,'Functions overlap; distance is not an age test',12);}else{b+=`<rect x="25" y="75" width="390" height="205" rx="15" fill="#719082"/><path d="M30 225L410 120" stroke="#d9d6c6" stroke-width="15"/>`+house(65,95,1.2)+house(125,115,1)+`<rect x="280" y="190" width="95" height="65" fill="#a9bd85" stroke="#e0e6cf"/>`+txt(293,228,'Fields',12)+txt(240,93,'Mixed edge uses',13)+txt(20,320,'Housing · transport · open land · recreation',12);}c='Original schematic, not a London satellite image or mapped land-use boundary. Zones describe common functions; real uses overlap and transport corridors and planning alter the pattern.';}
  else if(v==='centres'){b=txt(20,28,'A CITY WITH MULTIPLE CENTRES',15)+line('M25 185Q100 120 180 182T320 180T420 200','#8bbacf',15)+dot(155,135,10)+dot(225,165,10)+dot(330,150,10)+dot(245,285,10)+txt(20,102,'West End',13)+line('M90 108L150 130','#c6d8d9',1)+txt(200,95,'City',13)+line('M215 101L225 150','#c6d8d9',1)+txt(295,105,'Canary Wharf',13)+line('M330 113V135','#c6d8d9',1)+txt(266,290,'Croydon',13)+txt(20,332,'Approximate relationships · not to scale · N ↑',11);c='Selected London centres have different specialisms and mixed uses. Approximate relationships show that London is not one CBD surrounded by uniform rings; this is not surveyed geometry.';}
  else{b=txt(20,28,'BUILDING AGE ≠ DISTANCE RULE',15)+house(40,80,1.4,'#d6b49f')+towers(205,75,3)+house(340,95,1.2)+txt(20,197,'Spitalfields',13)+txt(20,218,'18th-century houses',11)+txt(180,197,'Docklands',13)+txt(180,218,'1980s+ renewal',11)+txt(325,197,'Becontree',13)+txt(325,218,'1921 start',11)+line('M30 250H405','#d4c5b1',2)+txt(20,282,'Survival, redevelopment and reuse mix ages',12)+txt(20,330,'Original icons, not photographs of these buildings',11);c='Three dated case anchors, not a complete building survey. Spitalfields preserves earlier homes/workshops; Becontree shows planned suburban housing; Docklands redevelopment mixes new development with inherited features.';return fig(b,c)+`<p class="geo-caption">${link('https://historicengland.org.uk/research/results/reports/120-2000','Historic England: Spitalfields')} · ${link('https://historicengland.org.uk/education/schools-resources/educational-images/becontree-estate-barking-greater-london-epw017649','Historic England: Becontree')} · ${link('https://www.london.gov.uk/sites/default/files/gla_capital_gains_report_.pdf','GLA: Docklands regeneration')}</p>`;}
  return fig(b,c)+`<p class="geo-caption">${link('https://www.london.gov.uk/programmes-strategies/planning/london-plan/the-london-plan-2021-online/chapter-2-spatial-development-patterns','London Plan 2021, SD4/SD6: central and town-centre functions')}. Dated planning framework, not a claim about a later draft’s adoption.</p>`;
 }
 if(k==='city-london-movements'){
  if(v==='coexist'){b=txt(20,28,'PROCESSES CAN COEXIST',16)+panel(25,75,390,'Inner areas','Renewal and arrivals in some neighbourhoods')+panel(25,175,390,'Outer areas and beyond','Outward moves and new housing elsewhere')+txt(20,303,'One city ≠ one simultaneous stage everywhere',12);c='A broad urbanisation → suburbanisation → counter-urbanisation → re-urbanisation sequence is a framework, not a single city-wide switch. Multiple flows can occur in the same period.';}
  else{const label={suburban:['SUBURBANISATION','Inner London','London suburb'],counter:['COUNTER-URBANISATION','London','Smaller / rural settlement'],return:['RE-URBANISATION','Elsewhere','Inner-city renewal']}[v];b=txt(20,28,label[0],17)+towers(v==='return'?290:45,105,3)+house(v==='return'?60:300,130,1.35)+panel(20,235,190,label[1])+panel(225,235,195,label[2])+line('M90 210H350','#b7c9d0',3)+dot(90+260*t,210,9)+txt(20,320,`Household / activity position: ${t<.33?'origin':t<.85?'moving':'destination'}`,12);c=v==='suburban'?'A hypothetical residence shifts from inner London to a suburb; employment may remain central. Becontree from 1921 is a dated suburban example. Timing and dots are symbolic, not measured households.':v==='counter'?'A hypothetical residence moves from London towards a smaller or rural settlement. This goes beyond suburban relocation; a daily journey alone is not counter-urbanisation. No measured flow is shown.':'A hypothetical return of residents/activity to established urban land. Docklands redevelopment is a local case; it does not prove all former residents benefited or all London areas changed equally.';}
 }
 if(k==='city-london-migration'){
  if(v==='evidence')return londonEvidence('birthplace');
  if(v==='routes'){b=txt(20,28,'MIGRATION · DIFFERENT ORIGINS',14)+panel(20,65,175,'Elsewhere in UK','National migration')+panel(245,65,175,'Abroad','International migration')+panel(115,225,210,'London','Jobs / study / family / safety')+line('M105 142L185 220M330 142L255 220')+dot(105+80*t,142+78*t)+dot(330-75*t,142+78*t)+txt(20,330,'Departures also occur; motives can overlap',12);c='Two illustrative arrivals, not a measured flow map or a claim about any ethnic group. Migration can reflect jobs, study, family and safety; people also leave, and motives and constraints differ.';}
  else if(v==='services'){b=txt(20,28,'RESIDENTS BOTH USE AND PROVIDE SERVICES',12)+panel(20,75,170,'New residents','Different ages and needs')+panel(250,75,170,'Local services','Staff / users / resources')+line('M105 185H335M105 245H335')+dot(105+230*t,185)+dot(335-230*t,245)+txt(20,310,'Housing, funding and capacity mediate effects',12);c='Movement in both directions represents contributions and use, not measured service demand. Housing supply, affordability, age and public investment affect outcomes; migration alone is not a complete causal explanation.';}
  else{const incoming=800*t,outgoing=650*t;b=txt(20,28,'NET MIGRATION · INVENTED ONE-YEAR CASE',12)+panel(20,70,180,'Arrivals: '+Math.round(incoming),'Final 800')+panel(240,70,180,'Departures: '+Math.round(outgoing),'Final 650')+txt(75,218,'Net: '+Math.round(incoming-outgoing)+' residents',20)+txt(20,275,'Arrivals − departures; same boundary and period',12)+txt(20,320,'Births and deaths are separate components',12);c='Invented 800 arrivals minus 650 departures gives net migration +150 at the end. The accumulating display isolates arithmetic, not the timing or scale of actual London flows.';}
 }
 if(k==='city-london-census'){
  if(v!=='balance')return londonEvidence(v);
  const n=50*t-30*t+20*t;b=txt(20,28,'CHANGE · INVENTED POPULATION BALANCE',12)+panel(20,65,190,'Natural increase','Births − deaths: +50')+panel(230,65,190,'National net migration','Arrivals − departures: −30')+panel(20,165,190,'International net','Arrivals − departures: +20')+txt(235,208,'Total: '+Math.round(n),23)+txt(20,282,'+50 −30 +20 = +40 at the end',15)+txt(20,325,'Illustrative components, not observed London flows',11);c='A negative national-migration component can coexist with total growth. The invented final change is +40; the smooth accumulation is symbolic. Real estimates may include statistical adjustments.';
 }
 return fig(b,c)+(k==='city-london-migration'?`<p class="geo-caption">${link('https://www.towerhamlets.gov.uk/lgnl/leisure_and_culture/local_attractions/cultural_trail/cultural_trail.aspx','Tower Hamlets: Brick Lane migration history')} · ${link('https://www.london.gov.uk/sites/default/files/housing_in_london_2021_v1.pdf','GLA 2021 housing report, domestic migration by age')}. Local and dated evidence, not a universal migrant profile.</p>`:'');
}
